\set ON_ERROR_STOP on
BEGIN;
SELECT lab_assert('private helper denied to anon',NOT has_function_privilege('anon','office_private.presentation_permission(uuid,text)','EXECUTE'));
SELECT lab_assert('link direct insert revoked',NOT has_table_privilege('authenticated','presentation_access_links','INSERT'));
SELECT lab_assert('link direct update revoked',NOT has_table_privilege('authenticated','presentation_access_links','UPDATE'));
SELECT lab_assert('legacy global presentation policies removed',(SELECT count(*)=0 FROM pg_policies WHERE schemaname='public' AND tablename IN ('presentations','presentation_items','presentation_access_links') AND policyname LIKE 'Admins have full access%'));
SELECT lab_assert('three tables retain RLS',(SELECT bool_and(relrowsecurity) FROM pg_class WHERE oid IN ('presentations'::regclass,'presentation_items'::regclass,'presentation_access_links'::regclass)));
SET ROLE anon;
SET request.jwt.claim.role='anon';
SET request.jwt.claim.sub='';
SELECT lab_expect_error('anonymous direct presentation read denied',$$SELECT * FROM presentations$$,'permission denied for table presentations');
SELECT lab_expect_error('anonymous round RPC denied',$$SELECT create_next_presentation_round(lab_uuid(51))$$,'permission denied for function create_next_presentation_round');
SELECT lab_expect_error('anonymous link creation denied',$$SELECT create_presentation_access_link(lab_uuid(41))$$,'permission denied for function create_presentation_access_link');
SELECT lab_assert('public decision remains callable',has_function_privilege('anon','submit_public_presentation_decision(text,uuid,text,text)','EXECUTE'));
RESET ROLE;
SET ROLE authenticated;
SET request.jwt.claim.role='authenticated';
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000201';
SELECT lab_assert('global admin sees own presentation',(SELECT count(*)=1 FROM presentations WHERE id=lab_uuid(41)));
SELECT lab_assert('global admin cannot read foreign presentation',(SELECT count(*)=0 FROM presentations WHERE id=lab_uuid(42)));
SELECT lab_assert('global admin cannot read foreign item',(SELECT count(*)=0 FROM presentation_items WHERE id=lab_uuid(63)));
SELECT lab_assert('global admin cannot read foreign token metadata',(SELECT count(*)=0 FROM presentation_access_links WHERE id=lab_uuid(84)));
SELECT lab_expect_error('global admin cannot create foreign presentation',$$INSERT INTO presentations(client_id) VALUES(lab_uuid(12))$$,'new row violates row-level security policy for table "presentations"');
WITH changed AS (UPDATE presentations SET title='forbidden' WHERE id=lab_uuid(42) RETURNING id) SELECT lab_assert('foreign update affects zero rows',count(*)=0) FROM changed;
WITH changed AS (DELETE FROM presentation_items WHERE id=lab_uuid(63) RETURNING id) SELECT lab_assert('foreign deletion affects zero rows',count(*)=0) FROM changed;
SELECT lab_expect_error('presentation client cannot be reassigned',$$UPDATE presentations SET client_id=lab_uuid(12) WHERE id=lab_uuid(41)$$,'PRESENTATION_RELATION_IMMUTABLE');
SELECT lab_expect_error('item parent cannot be reassigned',$$UPDATE presentation_items SET presentation_id=lab_uuid(43) WHERE id=lab_uuid(61)$$,'PRESENTATION_RELATION_IMMUTABLE');
SELECT lab_expect_error('direct decision changes require RPC',$$UPDATE presentation_items SET client_approval_status='approved' WHERE id=lab_uuid(61)$$,'DECISION_RPC_REQUIRED');
SELECT lab_expect_error('terminal presentation state requires RPC',$$UPDATE presentations SET status='approved' WHERE id=lab_uuid(41)$$,'DECISION_RPC_REQUIRED');
INSERT INTO presentation_items(id,presentation_id,content_id) VALUES(lab_uuid(91),lab_uuid(41),lab_uuid(35));
SELECT lab_assert('own pending item persists',(SELECT count(*)=1 FROM presentation_items WHERE id=lab_uuid(91)));
DELETE FROM presentation_items WHERE id=lab_uuid(91);
SELECT lab_assert('owner can remove own item',(SELECT count(*)=0 FROM presentation_items WHERE id=lab_uuid(91)));
SELECT lab_expect_error('foreign item insert denied before RLS write',$$INSERT INTO presentation_items(presentation_id,content_id) VALUES(lab_uuid(42),lab_uuid(33))$$,'PRESENTATION_ITEM_CLIENT_MISMATCH');
SELECT lab_expect_error('direct feedback changes require RPC',$$UPDATE presentation_items SET client_feedback='bypass' WHERE id=lab_uuid(61)$$,'DECISION_RPC_REQUIRED');
SELECT lab_expect_error('preapproved inserts require RPC',$$INSERT INTO presentation_items(presentation_id,content_id,client_approval_status) VALUES(lab_uuid(41),lab_uuid(35),'approved')$$,'DECISION_RPC_REQUIRED');
SELECT lab_expect_error('foreign round denied despite global admin',$$SELECT create_next_presentation_round(lab_uuid(42))$$,'UNAUTHORIZED');
SELECT lab_expect_error('foreign link creation denied despite global admin',$$SELECT create_presentation_access_link(lab_uuid(42))$$,'UNAUTHORIZED');
SELECT lab_expect_error('expired link creation denied',$$SELECT create_presentation_access_link(lab_uuid(41),now()-interval '1 hour')$$,'INVALID_EXPIRATION_DATE');
WITH changed AS (UPDATE presentation_items SET presentation_notes='fictitious note' WHERE id=lab_uuid(61) RETURNING id) SELECT lab_assert('own notes remain editable',count(*)=1) FROM changed;
WITH changed AS (UPDATE presentation_items SET display_order=9 WHERE id=lab_uuid(61) RETURNING id) SELECT lab_assert('own order remains editable',count(*)=1) FROM changed;
SAVEPOINT cascade_deletion;
DELETE FROM presentations WHERE id=lab_uuid(43);
SELECT lab_assert('parent deletion cascades items',(SELECT count(*)=0 FROM presentation_items WHERE id=lab_uuid(64)));
SELECT lab_assert('parent deletion cascades links',(SELECT count(*)=0 FROM presentation_access_links WHERE id=lab_uuid(85)));
SELECT lab_assert('presentation deletion preserves original content',(SELECT count(*)=1 FROM contents WHERE id=lab_uuid(34)));
ROLLBACK TO SAVEPOINT cascade_deletion;
RELEASE SAVEPOINT cascade_deletion;
CREATE TEMP TABLE lab_link AS SELECT create_presentation_access_link(lab_uuid(41)) AS payload;
SELECT lab_assert('token creation returns valid synthetic capability',(SELECT length(payload->>'token')=64 FROM lab_link));
RESET ROLE;
SELECT lab_assert('token stored only as matching hash',(SELECT EXISTS(SELECT 1 FROM presentation_access_links l WHERE l.id=(payload->>'id')::uuid AND l.token_hash=encode(extensions.digest(convert_to(payload->>'token','UTF8'),'sha256'),'hex')) FROM lab_link));
SET ROLE authenticated;
SELECT lab_assert('revocation succeeds',(SELECT (revoke_presentation_access_link((payload->>'id')::uuid)).revoked_at IS NOT NULL FROM lab_link));
SELECT lab_assert('revocation is idempotent',(SELECT (revoke_presentation_access_link((payload->>'id')::uuid)).revoked_at IS NOT NULL FROM lab_link));
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000205';
SELECT lab_assert('second workspace owner reads its own presentation',(SELECT count(*)=1 FROM presentations WHERE id=lab_uuid(42)));
SELECT lab_assert('second workspace owner cannot read first workspace',(SELECT count(*)=0 FROM presentations WHERE id=lab_uuid(41)));
SELECT lab_expect_error('foreign owner cannot revoke known link',$$SELECT revoke_presentation_access_link((SELECT (payload->>'id')::uuid FROM lab_link))$$,'UNAUTHORIZED');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000203';
SELECT lab_assert('assigned operator reads assigned presentation',(SELECT count(*)=1 FROM presentations WHERE id=lab_uuid(41)));
SELECT lab_assert('assigned operator cannot read unassigned local presentation',(SELECT count(*)=0 FROM presentations WHERE id=lab_uuid(43)));
SELECT lab_assert('assigned operator cannot read foreign presentation',(SELECT count(*)=0 FROM presentations WHERE id=lab_uuid(42)));
SELECT lab_assert('legacy root read limitation remains visible',(SELECT count(*)=0 FROM contents WHERE id=lab_uuid(31)));
SELECT lab_expect_error('operator cannot use unassigned source',$$SELECT create_next_presentation_round(lab_uuid(43))$$,'UNAUTHORIZED');
SELECT lab_expect_error('operator cannot include foreign content',$$SELECT create_next_presentation_round(lab_uuid(51),ARRAY[lab_uuid(33)])$$,'INVALID_CONTENT_SELECTION');
SELECT lab_expect_error('operator cannot include missing content',$$SELECT create_next_presentation_round(lab_uuid(51),ARRAY[lab_uuid(999)])$$,'INVALID_CONTENT_SELECTION');
SELECT lab_expect_error('operator cannot include null content',$$SELECT create_next_presentation_round(lab_uuid(51),ARRAY[NULL::uuid])$$,'INVALID_CONTENT_SELECTION');
CREATE TEMP TABLE lab_round AS SELECT create_next_presentation_round(lab_uuid(51),ARRAY[lab_uuid(35),lab_uuid(36),lab_uuid(35)],'Fictitious next round') AS payload;
SELECT lab_assert('operator creates exactly two unique items',(SELECT (payload->>'items_count')::int=2 FROM lab_round));
SELECT lab_assert('new round preserves lineage',(SELECT EXISTS(SELECT 1 FROM presentations p WHERE p.id=(payload->'presentation'->>'id')::uuid AND p.previous_presentation_id=lab_uuid(51) AND p.presentation_series_id=lab_uuid(51) AND p.round_number=2 AND p.status='draft') FROM lab_round));
SELECT lab_assert('new items remain pending and unreviewed',(SELECT count(*)=2 AND bool_and(client_approval_status='pending' AND reviewed_at IS NULL) FROM presentation_items WHERE presentation_id=(SELECT (payload->'presentation'->>'id')::uuid FROM lab_round)));
SELECT lab_expect_error('second direct next round rejected',$$SELECT create_next_presentation_round(lab_uuid(51))$$,'ALREADY_HAS_NEXT_ROUND');
SELECT lab_assert('operator can issue own client link',create_presentation_access_link(lab_uuid(41))->>'presentation_id'=lab_uuid(41)::text);
SELECT lab_assert('operator RPC decision remains allowed',update_presentation_item_admin_decision(lab_uuid(61),'approved')->>'client_approval_status'='approved');
WITH changed AS (DELETE FROM presentation_items WHERE id=lab_uuid(61) RETURNING id) SELECT lab_assert('operation member cannot delete item',count(*)=0) FROM changed;
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000207';
SELECT lab_assert('view member can read presentation',(SELECT count(*)=1 FROM presentations WHERE id=lab_uuid(41)));
SELECT lab_assert('view member cannot read token metadata',(SELECT count(*)=0 FROM presentation_access_links));
WITH changed AS (UPDATE presentation_items SET presentation_notes='forbidden' WHERE id=lab_uuid(61) RETURNING id) SELECT lab_assert('view member cannot change notes',count(*)=0) FROM changed;
SELECT lab_expect_error('view member cannot create round',$$SELECT create_next_presentation_round(lab_uuid(53))$$,'UNAUTHORIZED');
SELECT lab_expect_error('view member cannot create link',$$SELECT create_presentation_access_link(lab_uuid(41))$$,'UNAUTHORIZED');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000204';
SELECT lab_assert('suspended membership sees no presentations',(SELECT count(*)=0 FROM presentations));
SELECT lab_expect_error('suspended membership cannot create round',$$SELECT create_next_presentation_round(lab_uuid(53))$$,'UNAUTHORIZED');
SET request.jwt.claim.sub='00000000-0000-0000-0000-000000000206';
SELECT lab_assert('member without module permission sees nothing',(SELECT count(*)=0 FROM presentations));
SET request.jwt.claim.sub='';
SELECT lab_assert('missing identity sees nothing',(SELECT count(*)=0 FROM presentations));
SELECT lab_expect_error('missing identity cannot create link',$$SELECT create_presentation_access_link(lab_uuid(41))$$,'AUTH_REQUIRED');
RESET ROLE;
SET ROLE service_role;
SET request.jwt.claim.role='service_role';
SELECT lab_assert('trusted service can create empty round',create_next_presentation_round(lab_uuid(53))->>'items_count'='0');
RESET ROLE;
\ir ../../supabase/migrations/20261010002848_scope_presentation_workflows_to_workspace.sql
SELECT lab_assert('reapply preserves only intended presentation policies',(SELECT count(*)=9 FROM pg_policies WHERE schemaname='public' AND tablename IN ('presentations','presentation_items','presentation_access_links')));
ROLLBACK;
